/* ----------------------------- Tailwind auto-carga ----------------------------- */
// Si el proyecto ya tiene Tailwind compilado, lo detecta y no hace nada.
// Si no, carga el CDN de Tailwind para que la página se vea correctamente.
function useTailwind() {
  const [ready, setReady] = useState(false);
  useEffect(() => {
    const probe = document.createElement("div");
    probe.className = "hidden";
    document.body.appendChild(probe);
    const has = getComputedStyle(probe).display === "none";
    document.body.removeChild(probe);
    if (has) { setReady(true); return; }

    let s = document.getElementById("tw-cdn");
    if (!s) {
      s = document.createElement("script");
      s.id = "tw-cdn";
      s.src = "https://cdn.tailwindcss.com";
      document.head.appendChild(s);
    }
    const done = () => setTimeout(() => setReady(true), 200);
    if (window.tailwind) done();
    else {
      s.addEventListener("load", done);
      s.addEventListener("error", () => setReady(true));
    }
    const fallback = setTimeout(() => setReady(true), 4000);
    return () => clearTimeout(fallback);
  }, []);
  return ready;
}

/* ----------------------------- helpers ----------------------------- */
const num = (v) => (v === "" || v === null || v === undefined || isNaN(Number(v)) ? null : Number(v));
const round1 = (v) => Math.round(v * 10) / 10;
const fmtP = (v) => {
  const n = round1(Number(v) || 0);
  return (n > 0 ? "+" : "") + n.toLocaleString("en-US", { maximumFractionDigits: 1 });
};
const fmtDate = (d) => {
  if (!d) return "—";
  const [y, m, day] = d.split("-");
  return `${day}/${m}/${y}`;
};
const localDate = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
};
const uid = () => Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
const MONTHS_ES = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
const monthLabel = (ym) => { const [y, m] = ym.split("-"); return `${MONTHS_ES[Number(m) - 1]} ${y}`; };
const inPeriod = (date, period) => {
  if (!period || period === "all") return true;
  const d = date || "";
  if (period === "cur") return d.startsWith(curYM());
  if (period.startsWith("y:")) return d.startsWith(period.slice(2) + "-");
  return d.startsWith(period.slice(2));
};
const isClosed = (t) => ["TP", "SL", "BE"].includes(t.status);
// Visible al público: cerradas (TP/SL/BE) y descartadas. Las ABIERTAS quedan ocultas (solo admin).
const isPublic = (t) => isClosed(t) || t.status === "Descartada" || !!t.discarded;

function guessSub(asset) {
  const a = (asset || "").toUpperCase();
  if (/XAU|XAG|GOLD|SILVER/.test(a)) return "Oro/Metales";
  if (/NAS|US100|US30|US500|SPX|DJI|DAX|GER|UK100|JP225|NDX|USTEC/.test(a)) return "Índices";
  return "Forex";
}

// Tamaño de 1 pip (o punto) expresado en precio
// Sintéticos: 1 punto = el movimiento de precio que vale $1 por lote = 1 / contract size (según Specification de MT5 en Deriv).
// Boom, Crash, Volatility, Jump... tienen contract size 1 → 1 punto = 1.00 de precio.
// Step Index 100/200/300/400/500 tienen contract size 10 → 1 punto = 0.1; Step 1000/1500/2000 tienen 1 → 1 punto = 1.00.
const STEP_CONTRACT = { 100: 10, 200: 10, 300: 10, 400: 10, 500: 10, 1000: 1, 1500: 1, 2000: 1 };
function synthPip(asset) {
  const m = /^\s*STEP\b(?:\s*INDEX)?\s*(\d+)?/i.exec(asset || "");
  if (!m) return 1;
  const cs = STEP_CONTRACT[Number(m[1] || 100)] || 10;
  return 1 / cs;
}
function guessPip(asset, category, sub) {
  if (category === "SINTETICO") return synthPip(asset);
  const a = (asset || "").toUpperCase();
  if (/XAU|GOLD/.test(a)) return 0.1;
  if (/XAG|SILVER/.test(a)) return 0.01;
  if (/JPY/.test(a)) return 0.01;
  if (sub === "Índices" || guessSub(a) === "Índices") return 1;
  return 0.0001;
}

// Unidad según tipo de activo / broker
// Regla de unidades: TODOS los sintéticos (Deriv y Weltrade) = PUNTOS · CFDs = PIPS
const unitWord = (t) => (t.category === "SINTETICO" ? "puntos" : "pips");
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const unitName = (t) => cap(unitWord(t));

const KNOWN_SYMBOLS = ["XAUUSD", "XAGUSD", "NAS100", "US100", "USTEC", "US30", "US500", "SPX500", "GER40", "DAX40", "UK100", "JP225", "EURUSD", "GBPUSD", "USDJPY", "GBPJPY", "AUDUSD", "NZDUSD", "USDCAD", "USDCHF", "EURJPY", "EURGBP"];

function parseTpsText(text) {
  return String(text || "")
    .split(/[,;\s]+/)
    .map((tok) => {
      if (/^open$/i.test(tok)) return "OPEN";
      const n = num(tok);
      return n;
    })
    .filter((x) => x !== null && x !== "");
}

// Etiqueta de TP: TP1, TP2… (el abierto se muestra como "TP4 OPEN")
const tpLabel = (i, lvl) => (lvl === "OPEN" ? `TP${i + 1} OPEN` : `TP${i + 1}`);

/* ----------------------------- Clasificación automática de activos ----------------------------- */
// DERIV (sintéticos): BOOM, CRASH, VOLATILITY/VOLATILITYS/VIX, STEP/STEP INDEX/MULTI STEP, JUMP, DEX
const SYNTH_DERIV = /\b(?:BOOM|CRASH|VOLATILITYS?|VIX|MULTI\s*STEP|STEP(?:\s*INDEX)?|JUMP|DEX)/i;
// WELTRADE (sintéticos, en PUNTOS): PAINX, GAINX, FX VOL, SFX VOL, FLIPX, SWITCHX, BREAKX, TRENDX
const SYNTH_WELTRADE = /\b(?:MAX\s*PAINX|MAX\s*GAINX|PAINX|GAINX|S?FX\s*VOL|FLIPX|SWITCHX|BREAKX|TRENDX)/i;

// Para extraer el activo de un texto largo se exige el número del índice (evita falsos positivos como "step by step")
const SYN_EXTRACT = [
  /\b(?:MAX\s*)?(?:PAINX|GAINX)\s*\d{1,4}/i,
  /\bS?FX\s*VOL\s*\d{1,4}/i,
  /\b(?:FLIPX|SWITCHX|BREAKX|TRENDX)(?:\s*\d{1,4})?/i,
  /\bVOLATILITYS?(?:\s*(?:CRASH|BOOM))?\s*\d{1,4}(?:\s*\(\s*1S\s*\))?/i,
  /\b(?:BOOM|CRASH|JUMP|DEX|VIX)\s*\d{1,4}/i,
  /\b(?:MULTI\s*STEP|STEP\s*INDEX)(?:\s*\d{1,4})?|\bSTEP\s*\d{1,4}/i,
];

function findSynthetic(text) {
  let best = null;
  SYN_EXTRACT.forEach((re) => {
    const m = re.exec(text);
    if (m && (best === null || m.index < best.index)) best = m;
  });
  return best ? best[0].toUpperCase().replace(/\s+/g, " ").replace(/\s*\(\s*1S\s*\)/, " (1S)").trim() : "";
}

// Devuelve { category, broker, sub } o null si no se reconoce el activo
function classifyAsset(asset) {
  const a = String(asset || "").toUpperCase().trim();
  if (!a) return null;
  if (SYNTH_WELTRADE.test(a)) return { category: "SINTETICO", broker: "WELTRADE", sub: "" };
  if (SYNTH_DERIV.test(a)) return { category: "SINTETICO", broker: "DERIV", sub: "" };
  const compact = a.replace(/[\s/._-]/g, "");
  if (/XAU|XAG|GOLD|SILVER|NAS|US100|US30|US500|SPX|DJI|DAX|GER\d|UK100|JP225|NDX|USTEC/.test(a) || /^[A-Z]{6}$/.test(compact)) {
    return { category: "CFD", broker: "", sub: guessSub(a) };
  }
  return null;
}

// Interpreta señales completas (Pair/Side/Entry/TP/SL, BUY NOW / Take Profit n) y formatos cortos
// como "CRASH 900 SELL 16792". SL y TP pueden ser precios o distancias ("SL 20 PTS", "TP: 300 PTS").
function parseSignal(raw) {
  const text = String(raw || "").replace(/\r/g, "");
  const N = "([0-9][0-9,]*\\.?[0-9]*)";
  const UNIT = "(?:[ \\t]*(pts?|points?|puntos?|ptos?|pips?)\\b)?";
  const sep = "[ \\t]*[:\\-]?[ \\t]*";
  const toNum = (s) => Number(String(s).replace(/,/g, ""));
  const r5 = (x) => Number(x.toFixed(5));
  const out = { raw: text.trim(), asset: "", category: "CFD", broker: "", sub: "Forex", direction: "BUY", entry1: "", entry2: "", sl: "", tps: [], notes: "", warnings: [] };

  // ---- Activo ----
  let m = /pair\s*[:\-]\s*([^\n]+)/i.exec(text);
  if (m) {
    const clean = m[1].replace(/[^A-Za-z0-9 ()./_-]/g, "").trim();
    out.asset = classifyAsset(clean)?.category === "SINTETICO" ? clean.toUpperCase().replace(/\s+/g, " ") : clean.replace(/[./_\s-]/g, "").toUpperCase();
  }
  if (!out.asset) out.asset = findSynthetic(text);
  if (!out.asset) {
    const up = text.toUpperCase();
    const k = KNOWN_SYMBOLS.find((s) => up.includes(s));
    if (k) out.asset = k;
  }
  const cls = classifyAsset(out.asset);
  if (cls) { out.category = cls.category; out.broker = cls.broker; out.sub = cls.sub; }

  // ---- Entradas ----
  const e1m = new RegExp("(?:\\bentry|\\bE)[ \\t]*#?1\\b" + sep + N, "i").exec(text);
  const e2m = new RegExp("(?:\\bentry|\\bE)[ \\t]*#?2\\b" + sep + N, "i").exec(text);
  if (e1m || e2m) {
    if (e1m) out.entry1 = toNum(e1m[1]);
    if (e2m) out.entry2 = toNum(e2m[1]);
  } else {
    const rg = new RegExp("\\bentry[ \\t]*(?:zone|range|price)?" + sep + N + "[ \\t]*(?:-|–|—|to|/)[ \\t]*" + N, "i").exec(text);
    if (rg) {
      out.entry1 = toNum(rg[1]);
      out.entry2 = toNum(rg[2]);
    } else {
      const g = new RegExp("\\bentry[ \\t]*(?:price)?" + sep + N, "i").exec(text);
      if (g) out.entry1 = toNum(g[1]);
    }
  }
  // Formato corto: "CRASH 900 SELL 16792" → el precio que sigue a la dirección es la entrada
  let shortDir = null;
  if (out.entry1 === "") {
    const sm = new RegExp("\\b(buy|sell|long|short)\\b(?:[ \\t]+(?:limit|stop|now))?[ \\t]*(?:@|at\\b)?[ \\t]*[:\\-]?[ \\t]*" + N, "i").exec(text);
    if (sm) { out.entry1 = toNum(sm[2]); shortDir = /buy|long/i.test(sm[1]) ? "BUY" : "SELL"; }
  }

  // ---- Dirección ----
  let dirUnknown = false;
  if (shortDir) out.direction = shortDir;
  else if (/side\s*[:\-]?[^\n]*\b(short|sell)\b/i.test(text) || /\bsell\s+now\b/i.test(text)) out.direction = "SELL";
  else if (/side\s*[:\-]?[^\n]*\b(long|buy)\b/i.test(text) || /\bbuy\s+now\b/i.test(text)) out.direction = "BUY";
  else if (/\b(sell|short)\b/i.test(text)) out.direction = "SELL";
  else if (/\b(buy|long)\b/i.test(text)) out.direction = "BUY";
  else dirUnknown = true;

  // ---- SL y TP (precio absoluto o distancia) ----
  const slm = new RegExp("(?:stop[ \\t]*loss|\\bSL)\\s*[:\\-]?\\s*" + N + UNIT, "i").exec(text);
  const slRaw = slm ? { v: toNum(slm[1]), unit: slm[2] || "" } : null;

  const tpRaw = [];
  const seen = {};
  const re = new RegExp("(?:take[ \\t]*profit|\\bTP)[ \\t]*(\\d)(?![\\d.,])[ \\t]*[:\\-]?[ \\t]*" + N + UNIT, "gi");
  while ((m = re.exec(text))) seen[Number(m[1])] = { v: toNum(m[2]), unit: m[3] || "" };
  Object.keys(seen).map(Number).sort((a, b) => a - b).forEach((k) => tpRaw.push(seen[k]));
  if (!tpRaw.length) {
    m = new RegExp("(?:take[ \\t]*profit|\\bTP)[ \\t]*[:\\-]?[ \\t]*" + N + UNIT, "i").exec(text);
    if (m) tpRaw.push({ v: toNum(m[1]), unit: m[2] || "" });
  }
  const tpOpen = /\b(?:tp|take[ \t]*profit)[ \t]*\d?[ \t]*[:\-]?[ \t]*open\b/i.test(text);

  // Sin palabra BUY/SELL: se deduce por la posición del SL respecto a la entrada
  if (dirUnknown && out.entry1 !== "" && slRaw && !slRaw.unit && !(out.entry1 >= 100 && slRaw.v < out.entry1 * 0.1)) out.direction = slRaw.v > out.entry1 ? "SELL" : "BUY";

  const ps = guessPip(out.asset, out.category, out.sub);
  const sign = out.direction === "SELL" ? -1 : 1;
  const hasEntry = out.entry1 !== "";
  // Convierte una distancia a unidades de precio
  // (la escala `ps` ya vale 1 en índices y en la mayoría de sintéticos, y 0.1 en Step Index: 1000 puntos = 100 de precio)
  const distPrice = (v) => v * ps;
  const distUnit = out.category === "SINTETICO" ? "puntos" : "pips";
  const looksLikeDistance = (v) => hasEntry && out.entry1 >= 100 && v < out.entry1 * 0.1;

  if (slRaw) {
    if (slRaw.unit || looksLikeDistance(slRaw.v)) {
      if (hasEntry) {
        const d = slRaw.unit ? distPrice(slRaw.v, slRaw.unit) : slRaw.v;
        out.sl = r5(out.entry1 - sign * d);
        if (!slRaw.unit) out.warnings.push(`SL interpretado como distancia de ${slRaw.v} ${distUnit} desde la entrada. Revísalo.`);
      } else out.warnings.push("El SL viene como distancia pero no se detectó la entrada.");
    } else out.sl = slRaw.v;
  }
  tpRaw.forEach((t) => {
    if (t.unit || looksLikeDistance(t.v)) {
      if (hasEntry) {
        const d = t.unit ? distPrice(t.v, t.unit) : t.v;
        out.tps.push(r5(out.entry1 + sign * d));
        if (!t.unit) out.warnings.push(`TP interpretado como distancia de ${t.v} ${distUnit} desde la entrada. Revísalo.`);
      } else out.warnings.push("El TP viene como distancia pero no se detectó la entrada.");
    } else out.tps.push(t.v);
  });
  if (tpOpen) out.tps.push("OPEN");

  if (!out.asset) out.warnings.push("No se detectó el activo: escríbelo manualmente.");
  else if (!cls) out.warnings.push("Activo no reconocido: elige categoría y broker manualmente.");
  if (out.entry1 === "") out.warnings.push("No se detectó la entrada.");
  if (out.sl === "") out.warnings.push("No se detectó el SL.");
  if (!out.tps.length) out.warnings.push("No se detectaron niveles de TP.");
  if (out.entry2 !== "") out.warnings.push("Hay dos entradas: elige cuál(es) se activó en la gestión.");
  if (out.entry1 !== "" && out.sl !== "" && (out.direction === "SELL") !== (out.sl > out.entry1)) {
    out.warnings.push("La dirección no coincide con la posición del SL respecto a la entrada. Revísalo.");
  }
  return out;
}

// Reduce la imagen para que quepa en el almacenamiento del navegador
function compressImage(file, maxW = 1280, quality = 0.72) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = reject;
    reader.onload = () => {
      const img = new Image();
      img.onerror = reject;
      img.onload = () => {
        const scale = Math.min(1, maxW / img.width);
        const c = document.createElement("canvas");
        c.width = Math.round(img.width * scale);
        c.height = Math.round(img.height * scale);
        c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
        resolve(c.toDataURL("image/jpeg", quality));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

/* ----------------------------- Modelo: entradas, patas y pips ----------------------------- */
// Cada operación tiene Entry 1 y (opcional) Entry 2. "activation" indica cuáles se activaron.
// Cada entrada activada es una "pata" (leg) con su propio resultado en pips/puntos.
const hasE2 = (t) => num(t.entry2) !== null;
// Compatibilidad con datos antiguos: el journal ya no registra parciales. Si una entrada cerrada traía
// parciales guardados, se pliegan en su resultado (el total de la operación NO cambia) y el nivel de TP
// etiquetado queda como "reached" (solo lectura, para no perder el objetivo alcanzado histórico).
const legacyLeg = (L) => {
  if (!L || (L.partials === undefined && L.partialPips === undefined && L.partialTps === undefined)) return L;
  const { partials, partialPips, partialTps, ...rest } = L;
  const closed = !!rest.status && rest.status !== "Abierta" && rest.status !== "Pendiente" && !(rest.status === "MANUAL" && num(rest.pips) === null);
  const sum = round1((partialPips || []).reduce((a, x) => a + (Number(x) || 0), 0));
  const tags = (partialTps || []).filter((i) => i !== null && i !== undefined && i !== "").map(Number).filter(Number.isFinite);
  const out = { ...rest };
  if (closed && sum) out.pips = round1((num(rest.pips) ?? 0) + sum);
  if (tags.length) out.reached = Math.max(...tags, num(rest.reached) ?? -1);
  return out;
};
const stripLegacy = (t) => {
  if (!t.legs) return t;
  let changed = false;
  const legs = {};
  Object.keys(t.legs).forEach((k) => { const n = legacyLeg(t.legs[k]); if (n !== t.legs[k]) changed = true; legs[k] = n; });
  return changed ? { ...t, legs } : t;
};
const legKeys = (t) => (hasE2(t) ? (t.activation === "BOTH" ? ["e1", "e2"] : t.activation === "E2" ? ["e2"] : ["e1"]) : ["e1"]);
const entryOf = (t, k) => num(k === "e1" ? t.entry1 : t.entry2);
const legOf = (t, k) => (t.legs && t.legs[k]) || { status: "Abierta", exit: "", pips: "", tpIdx: null };

function calcPips(t, k, price) {
  const e = entryOf(t, k);
  const p = num(price);
  const ps = num(t.pipSize) || 1;
  if (e === null || p === null) return null;
  const dir = t.direction === "SELL" ? -1 : 1;
  return round1(((p - e) * dir) / ps);
}

// Recalcula con la escala actual los resultados automáticos de cada entrada (SL y TP con precio). BE, Cierre Manual y TP open no se tocan.
function rescaleLegs(t) {
  const legs = { ...(t.legs || {}) };
  Object.keys(legs).forEach((k) => {
    const L = legs[k];
    if (!L) return;
    if (L.status === "SL") {
      const p = calcPips(t, k, t.sl);
      if (p !== null) legs[k] = { ...L, exit: t.sl, pips: p };
    } else if (L.status === "TP" && L.exit !== "OPEN" && t.tps && t.tps[L.tpIdx] !== undefined && t.tps[L.tpIdx] !== "OPEN") {
      const lvl = t.tps[L.tpIdx];
      const p = calcPips(t, k, lvl);
      if (p !== null) legs[k] = { ...L, exit: lvl, pips: p };
    }
  });
  return legs;
}

function riskPips(t, k) {
  const e = entryOf(t, k);
  const sl = num(t.sl);
  const ps = num(t.pipSize) || 1;
  if (e === null || sl === null) return 0;
  return Math.abs(e - sl) / ps;
}

function legResults(t) {
  if (t.discarded) return [];
  const out = [];
  legKeys(t).forEach((k) => {
    const L = legOf(t, k);
    if (!L.status || L.status === "Abierta" || L.status === "Pendiente") return;
    if (L.status === "MANUAL" && num(L.pips) === null) return; // Cierre manual: se registra al escribir los pips/puntos
    const p = num(L.pips) ?? 0;
    const risk = riskPips(t, k);
    out.push({ key: k, status: L.status, pips: p, r: risk ? p / risk : 0 });
  });
  return out;
}

// Calcula estado, pips totales y R de la operación a partir de sus patas
function recompute(t0) {
  const t = stripLegacy(t0);
  if (t.discarded) return { ...t, status: "Descartada", pips: 0, r: 0 };
  const keys = legKeys(t);
  const res = legResults(t);
  const open = res.length < keys.length;
  const total = res.reduce((a, x) => a + x.pips, 0);
  const r = res.reduce((a, x) => a + x.r, 0);
  let status;
  if (open) status = keys.every((k) => legOf(t, k).status === "Pendiente") ? "Pendiente" : "Abierta";
  else if (res.every((x) => x.status === "BE")) status = "BE";
  else status = total > 0 ? "TP" : total < 0 ? "SL" : "BE";
  return { ...t, status, pips: round1(total), r: Math.round(r * 100) / 100 };
}

// Mayor TP alcanzado por alguna pata (para marcar los TPs en verde): el TP en que cerró cada entrada
// (o "reached", solo en datos antiguos que traían parciales etiquetados con un TP).
const hitMax = (t) => {
  if (t.discarded) return -1;
  let best = -1;
  legKeys(t).forEach((k) => {
    const L = legOf(t, k);
    if (L.status === "TP" && L.tpIdx !== null && L.tpIdx !== undefined) best = Math.max(best, L.tpIdx);
    const r = num(L.reached);
    if (r !== null) best = Math.max(best, r);
    // BE con ganancia: si los pips/puntos reales alcanzan la distancia de un TP, ese TP se tocó antes de volver a BE
    const bp = L.status === "BE" ? num(L.pips) : null;
    if (bp !== null && bp > 0) (t.tps || []).forEach((lvl, i) => {
      if (lvl === "OPEN") return;
      const need = calcPips(t, k, lvl);
      if (need !== null && need > 0 && bp + 0.05 >= need) best = Math.max(best, i);
    });
  });
  return best;
};
// Cómo terminó una operación cerrada, para el reporte: MANUAL | OPEN (TP abierto, dejada correr) | TP | BE | SL
const isRun = (L) => L.status === "TP" && L.exit === "OPEN";
const outcomeOf = (t) => {
  if (t.discarded || !isClosed(t)) return null;
  const ls = legKeys(t).map((k) => legOf(t, k));
  if (ls.some((L) => L.status === "MANUAL")) return "MANUAL";
  if (ls.some(isRun)) return "OPEN";
  return t.status;
};
// Pips de las entradas que cerraron de una forma concreta (cierre manual / TP abierto)
const legPipsWhere = (t, pred) => round1(legKeys(t).reduce((a, k) => (pred(legOf(t, k)) ? a + (num(legOf(t, k).pips) ?? 0) : a), 0));

const legSummary = (t, k) => {
  const L = legOf(t, k);
  if (L.status === "Pendiente") return "Orden pendiente";
  if (!L.status || L.status === "Abierta") return "Activa";
  const tp = L.status === "TP" && t.tps && t.tps[L.tpIdx] !== undefined ? tpLabel(L.tpIdx, t.tps[L.tpIdx]) : L.status === "MANUAL" ? "Cierre manual" : L.status;
  const p = num(L.pips);
  if (p === null) return `${tp} · sin pips`;
  return `${tp} · ${fmtP(p)} ${unitWord(t)}`;
};

function computeMetrics(list) {
  const live = list.filter((t) => t.status !== "Descartada");
  const legs = live.flatMap(legResults);
  const closed = live.filter((t) => ["TP", "SL", "BE"].includes(t.status));
  const wins = closed.filter((t) => t.status === "TP");
  const losses = closed.filter((t) => t.status === "SL");
  const be = closed.filter((t) => t.status === "BE");
  const open = live.filter((t) => t.status === "Abierta").length;
  const pending = live.filter((t) => t.status === "Pendiente").length;
  const discarded = list.length - live.length;
  const decisive = wins.length + losses.length;
  const winRate = decisive ? (wins.length / decisive) * 100 : 0;
  const totalPips = legs.reduce((a, x) => a + x.pips, 0);
  const grossWin = legs.filter((x) => x.pips > 0).reduce((a, x) => a + x.pips, 0);
  const grossLoss = Math.abs(legs.filter((x) => x.pips < 0).reduce((a, x) => a + x.pips, 0));
  const profitFactor = grossLoss ? grossWin / grossLoss : grossWin ? Infinity : 0;
  const totalR = legs.reduce((a, x) => a + x.r, 0);
  const avgR = legs.length ? totalR / legs.length : 0;
  return { open, pending, executed: closed.length, wins: wins.length, losses: losses.length, be: be.length, discarded, winRate, totalPips, profitFactor, totalR, avgR, total: list.length, legsCount: legs.length };
}

/* ----------------------------- Migración de formato anterior ----------------------------- */

// Convierte operaciones del formato anterior (v1, con lotes y $) al nuevo
function migrateLegacy(t) {
  const cat = t.category;
  const pipSize = guessPip(t.asset, cat, t.sub);
  const entry = num(t.entry);
  const exit = num(t.exit);
  const dir = t.direction === "SELL" ? -1 : 1;
  const st = ["TP", "SL", "BE"].includes(t.status) ? t.status : "Abierta";
  let pips = "";
  if (st === "BE") pips = 0;
  else if (st !== "Abierta" && entry !== null && exit !== null) pips = round1(((exit - entry) * dir) / pipSize);
  const levels = Array.isArray(t.tps) && t.tps.length ? t.tps.map((x) => x.level) : num(t.tp) !== null ? [num(t.tp)] : [];
  const hits = Array.isArray(t.tps) ? t.tps.map((x, i) => (x.hit ? i : -1)).filter((i) => i >= 0) : [];
  const tpIdx = st === "TP" ? (hits.length ? Math.max(...hits) : levels.length ? levels.length - 1 : null) : null;
  return recompute({
    id: t.id, date: t.date, category: cat, sub: t.sub || "", broker: t.broker || "", asset: t.asset, direction: t.direction,
    entry1: t.entry ?? "", entry2: "", activation: "E1", sl: t.sl ?? "", tps: levels, pipSize,
    legs: { e1: { status: st, exit: t.exit ?? "", pips, tpIdx } },
    discarded: t.status === "Descartada", raw: t.raw || "", notes: t.notes || "", tags: t.tags || [],
  });
}

const normalizeAny = (t) => (t.entry1 === undefined ? migrateLegacy(t) : recompute(t));


/* ============================================================
   ALMACENAMIENTO EN GITHUB (data/trades.json)
   - Sin localStorage. La fuente de verdad es un JSON dentro del repositorio.
   - Público: lee el archivo (raw.githubusercontent.com) y solo muestra cerradas/descartadas.
   - Admin: entra pegando su TOKEN de GitHub (nunca va escrito en el código). El token
     vive solo en sessionStorage (se borra al cerrar la pestaña) y se usa para
     escribir el archivo con la API de contenidos de GitHub.
   Guía y recomendaciones de seguridad: GITHUB_SETUP.md
   ============================================================ */
const GH = {
  repo: "hajarxo/borkaifx-elite",
  branch: "main",
  tradesPath: "data/trades.json",
  openPath: "data/open.enc.json", // señales abiertas, cifradas (solo el admin puede leerlas)
};
const cloudOn = () => true;
const AUTH_KEY = "borkaifx_elite_gh_session";
const PUBLIC_STATUSES = ["TP", "SL", "BE", "Descartada"];

const readAuth = () => { try { return JSON.parse(sessionStorage.getItem(AUTH_KEY) || "null"); } catch (e) { return null; } };
const writeAuth = (a) => { try { a ? sessionStorage.setItem(AUTH_KEY, JSON.stringify(a)) : sessionStorage.removeItem(AUTH_KEY); } catch (e) {} };

const cloudErr = (msg, code) => Object.assign(new Error(msg), { code });
const ghApi = (path) => `https://api.github.com/repos/${GH.repo}/contents/${path}`;
const ghHeaders = (token) => ({ Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", Authorization: `Bearer ${token}` });
const b64decode = (b64) => { const bin = atob(String(b64).replace(/\s/g, "")); return new TextDecoder().decode(Uint8Array.from(bin, (c) => c.charCodeAt(0))); };
const b64encode = (str) => { const bytes = new TextEncoder().encode(str); let bin = ""; bytes.forEach((b) => { bin += String.fromCharCode(b); }); return btoa(bin); };

// Valida el token: debe poder ESCRIBIR en el repositorio
async function cloudSignIn(token) {
  token = String(token || "").trim();
  if (!token) throw cloudErr("EMPTY", 401);
  const r = await fetch(`https://api.github.com/repos/${GH.repo}`, { headers: ghHeaders(token), cache: "no-store" });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw cloudErr(j?.message || "AUTH", r.status === 404 ? 401 : r.status);
  if (j.permissions && !j.permissions.push) throw cloudErr("SIN_PERMISO_DE_ESCRITURA", 401);
  writeAuth({ token });
}
const authToken = () => { const a = readAuth(); if (!a?.token) throw cloudErr("NO_AUTH", 401); return a.token; };

// Lee un JSON del repo. Admin: API con token (siempre fresco, devuelve sha). Público: raw (sin token).
async function ghReadJson(path, admin, fallback = []) {
  if (admin) {
    const r = await fetch(`${ghApi(path)}?ref=${encodeURIComponent(GH.branch)}&t=${Date.now()}`, { headers: ghHeaders(authToken()), cache: "no-store" });
    if (r.status === 404) return { data: fallback, sha: null };
    const j = await r.json().catch(() => ({}));
    if (!r.ok) throw cloudErr(j?.message || `HTTP ${r.status}`, r.status === 403 ? 401 : r.status);
    let data = fallback;
    try { data = JSON.parse(b64decode(j.content || "") || "null") ?? fallback; } catch (e) {}
    return { data, sha: j.sha };
  }
  const r = await fetch(`https://raw.githubusercontent.com/${GH.repo}/${GH.branch}/${path}?t=${Date.now()}`, { cache: "no-store" });
  if (r.status === 404) return { data: fallback, sha: null };
  if (!r.ok) throw cloudErr(`HTTP ${r.status}`, r.status);
  let data = fallback;
  try { data = JSON.parse((await r.text()) || "null") ?? fallback; } catch (e) {}
  return { data, sha: null };
}

async function ghWriteJson(path, list, sha, message) {
  const body = { message, content: b64encode(JSON.stringify(list, null, 2) + "\n"), branch: GH.branch };
  if (sha) body.sha = sha;
  const r = await fetch(ghApi(path), { method: "PUT", headers: { ...ghHeaders(authToken()), "Content-Type": "application/json" }, body: JSON.stringify(body) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw cloudErr(j?.message || `HTTP ${r.status}`, r.status === 403 || r.status === 401 ? 401 : r.status);
  return j;
}

// ---- Señales ABIERTAS: nunca van en claro al repositorio (puede ser público).
// Se guardan cifradas (AES-GCM) en data/open.enc.json con una clave derivada del TOKEN del admin.
const subtle = () => (typeof crypto !== "undefined" && crypto.subtle) || null;
const b64bytes = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
const bytesB64 = (u8) => { let bin = ""; u8.forEach((b) => { bin += String.fromCharCode(b); }); return btoa(bin); };
async function openKey(token, salt) {
  const base = await subtle().importKey("raw", new TextEncoder().encode(token), "PBKDF2", false, ["deriveKey"]);
  return subtle().deriveKey({ name: "PBKDF2", salt, iterations: 150000, hash: "SHA-256" }, base, { name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
}
async function encryptOpen(list, token) {
  if (!subtle()) throw cloudErr("NO_CRYPTO", 500);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const key = await openKey(token, salt);
  const buf = await subtle().encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(JSON.stringify(list)));
  return { v: 1, salt: bytesB64(salt), iv: bytesB64(iv), data: bytesB64(new Uint8Array(buf)) };
}
async function decryptOpen(env, token) {
  const key = await openKey(token, b64bytes(env.salt));
  const buf = await subtle().decrypt({ name: "AES-GCM", iv: b64bytes(env.iv) }, key, b64bytes(env.data));
  const list = JSON.parse(new TextDecoder().decode(buf));
  return Array.isArray(list) ? list : [];
}
// Lee las abiertas. Si no se pueden descifrar (token distinto al que las cifró) -> locked: no se sobrescribe nada.
async function readOpen() {
  const { data, sha } = await ghReadJson(GH.openPath, true, null);
  if (!data || !data.data) return { list: [], sha, locked: false };
  try { return { list: await decryptOpen(data, authToken()), sha, locked: false }; }
  catch (e) { return { list: [], sha, locked: true }; }
}
const sortTrades = (a, b) => ((a.date || "") < (b.date || "") ? -1 : (a.date || "") > (b.date || "") ? 1 : String(a.id) < String(b.id) ? -1 : 1);

// Descarga: el público lee solo data/trades.json (cerradas/descartadas). El admin además descifra las abiertas.
let openLocked = false;
async function cloudPull(admin) {
  const { data } = await ghReadJson(GH.tradesPath, admin);
  let raw = Array.isArray(data) ? data : [];
  if (admin) {
    const o = await readOpen();
    openLocked = o.locked;
    raw = raw.concat(o.list);
  }
  const out = [];
  raw.forEach((t) => { try { const n = normalizeAny(t); if (admin || isPublic(n)) out.push(n); } catch (e) {} });
  return out.sort(sortTrades);
}

// Un commit por archivo modificado (agregar/modificar/descartar/borrar). Reintenta si otro dispositivo escribió antes.
async function cloudCommit(ups, dels) {
  const msg = `Track Record: ${ups.length ? `${ups.length} guardada(s)` : ""}${ups.length && dels.length ? ", " : ""}${dels.length ? `${dels.length} eliminada(s)` : ""}`;
  for (let attempt = 0; attempt < 4; attempt++) {
    const pub = await ghReadJson(GH.tradesPath, true);
    const opn = await readOpen();
    if (opn.locked) throw cloudErr("OPEN_LOCKED", 423);
    const pm = new Map((Array.isArray(pub.data) ? pub.data : []).map((t) => [t.id, t]));
    const om = new Map(opn.list.map((t) => [t.id, t]));
    const before = [JSON.stringify([...pm.values()].sort(sortTrades)), JSON.stringify([...om.values()].sort(sortTrades))];
    dels.forEach((id) => { pm.delete(id); om.delete(id); });
    ups.forEach((t) => { if (isPublic(t)) { pm.set(t.id, t); om.delete(t.id); } else { om.set(t.id, t); pm.delete(t.id); } });
    const pl = [...pm.values()].sort(sortTrades), ol = [...om.values()].sort(sortTrades);
    try {
      // primero se retira la señal de "abiertas" si pasó a pública, y se publica; el orden evita perderla
      if (JSON.stringify(pl) !== before[0]) await ghWriteJson(GH.tradesPath, pl, pub.sha, msg);
      if (JSON.stringify(ol) !== before[1]) await ghWriteJson(GH.openPath, await encryptOpen(ol, authToken()), opn.sha, `${msg} (abiertas, cifrado)`);
      return true;
    } catch (e) { if ((e.code === 409 || e.code === 422) && attempt < 3) continue; throw e; }
  }
  return null;
}

