// Pon en true para volver a mostrar el calendario anual (oculto temporalmente)
const SHOW_YEAR_CALENDAR = false;
function CalendarView({ trades: allTrades, isAdmin, unit, onOpen }) {
  // Las órdenes pendientes (aún no activadas) no cuentan: solo se muestran entradas ejecutadas
  const trades = useMemo(() => allTrades.filter((t) => t.status !== "Pendiente"), [allTrades]);
  const months = useMemo(() => Array.from(new Set(trades.map((t) => (t.date || "").slice(0, 7)).filter(Boolean))).sort().reverse(), [trades]);
  const [ym, setYm] = useState(null);
  const [selDay, setSelDay] = useState(null);
  const [sigTrade, setSigTrade] = useState(null); // señal original abierta en ventana flotante
  const [mode, setMode] = useState("month"); // month | year
  const [yearSel, setYearSel] = useState(null);

  const cur = ym || months[0] || curYM();
  const [y, mo] = cur.split("-").map(Number);
  const unitL = unit.toLowerCase();
  const today = localDate();

  const monthTrades = useMemo(() => trades.filter((t) => tdate(t).startsWith(cur)), [trades, cur]);
  const byDay = useMemo(() => {
    const map = {};
    monthTrades.forEach((t) => { const k = tdate(t); (map[k] = map[k] || []).push(t); });
    return map;
  }, [monthTrades]);
  const m = useMemo(() => computeMetrics(monthTrades), [monthTrades]);
  const closedTrades = useMemo(() => monthTrades.filter(isClosed), [monthTrades]);
  const best = useMemo(() => closedTrades.reduce((b, t) => (!b || t.pips > b.pips ? t : b), null), [closedTrades]);
  const worst = useMemo(() => closedTrades.reduce((b, t) => (!b || t.pips < b.pips ? t : b), null), [closedTrades]);

  // Semanas (domingo a sábado) con sus totales
  const weeks = useMemo(() => {
    const first = (new Date(y, mo - 1, 1).getDay() + 6) % 7;
    const dim = new Date(y, mo, 0).getDate();
    const cells = [...Array(first).fill(null), ...Array.from({ length: dim }, (_, i) => i + 1)];
    while (cells.length % 7) cells.push(null);
    const out = [];
    for (let i = 0; i < cells.length; i += 7) {
      const days = cells.slice(i, i + 7).map((d) => {
        if (d === null) return null;
        const key = `${cur}-${String(d).padStart(2, "0")}`;
        return { d, key, st: dayStats(byDay[key] || []) };
      });
      const real = days.filter(Boolean);
      out.push({
        days,
        pips: round1(real.reduce((a, x) => a + x.st.pips, 0)),
        traded: real.filter((x) => x.st.shown > 0).length,
      });
    }
    return out;
  }, [y, mo, cur, byDay]);

  const keepMonthSel = () => (selDay === "__month__" ? "__month__" : null);
  useEffect(() => { if (!selDay) return; const h = (e) => { if (e.key === "Escape") setSelDay(null); }; document.addEventListener("keydown", h); return () => document.removeEventListener("keydown", h); }, [selDay]);
  const go = (d) => { setYm(shiftMonth(cur, d)); setSelDay(keepMonthSel()); };
  const monthOptions = useMemo(() => Array.from(new Set([...months, curYM(), cur])).sort().reverse(), [months, cur]);

  // Curva de pips acumulados día a día del mes seleccionado
  const dim = new Date(y, mo, 0).getDate();
  const curve = useMemo(() => {
    const todayKey = localDate();
    const last = cur === todayKey.slice(0, 7) ? Number(todayKey.slice(8, 10)) : cur > todayKey.slice(0, 7) ? 0 : dim;
    let acc = 0;
    const pts = [];
    for (let d = 1; d <= last; d++) {
      const key = `${cur}-${String(d).padStart(2, "0")}`;
      const dp = dayStats(byDay[key] || []).pips;
      acc = round1(acc + dp);
      pts.push({ name: `Día ${d}`, d, equity: acc, day: dp });
    }
    return pts;
  }, [cur, dim, byDay]);

  // Vista anual: todos los años con datos, meses Ene-Dic y total
  const yearsAvail = useMemo(() => Array.from(new Set([curYM().slice(0, 4), ...trades.map((t) => (t.date || "").slice(0, 4)).filter(Boolean)])).sort().reverse(), [trades]);
  const yearCur = yearSel || (yearsAvail.includes(String(y)) ? String(y) : yearsAvail[0]);
  const yearTable = useMemo(() => yearsAvail.map((yy) => {
    const monthsRow = Array.from({ length: 12 }, (_, i) => {
      const key = `${yy}-${String(i + 1).padStart(2, "0")}`;
      return { key, st: dayStats(trades.filter((t) => (t.date || "").startsWith(key))) };
    });
    return { yy, monthsRow, tot: dayStats(trades.filter((t) => (t.date || "").startsWith(yy))) };
  }), [trades, yearsAvail]);
  const isMonthSel = selDay === "__month__";
  const dayList = isMonthSel ? [...monthTrades].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.asset < b.asset ? -1 : 1)) : selDay ? [...(byDay[selDay] || [])].sort((a, b) => (a.asset < b.asset ? -1 : 1)) : [];
  const dec = m.wins + m.losses;
  const pct = (n) => (m.executed ? Math.round((n / m.executed) * 100) : 0);
  const cols = {};
  const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

  return (
    <section className="space-y-3">
      {SHOW_YEAR_CALENDAR && <div className="flex flex-wrap justify-center gap-2">
        <button onClick={() => setMode("month")} className={`bx-pill ${mode === "month" ? "on" : ""}`}>📅 Vista mensual</button>
        <button onClick={() => setMode("year")} className={`bx-pill ${mode === "year" ? "on" : ""}`}>🗓 Calendario anual</button>
      </div>}

      {SHOW_YEAR_CALENDAR && mode === "year" && (() => {
        const row = yearTable.find((x) => x.yy === yearCur) || yearTable[0];
        const posM = row ? row.monthsRow.filter((x) => x.st.shown > 0 && x.st.pips > 0).length : 0;
        const actM = row ? row.monthsRow.filter((x) => x.st.shown > 0).length : 0;
        return (
          <div className="bx-card p-3 md:p-4" data-testid="year-view">
            <div className="flex items-center justify-center gap-3">
              <button onClick={() => { const i = yearsAvail.indexOf(yearCur); if (i < yearsAvail.length - 1) setYearSel(yearsAvail[i + 1]); }} className="bx-ghost" aria-label="Año anterior">‹</button>
              <div className="text-center" style={{ minWidth: 200 }}>
                <div className="text-xl md:text-2xl font-black">{yearCur}</div>
                <div className="text-[11px] bx-muted tracking-widest uppercase">Resultados por mes en {unit}</div>
              </div>
              <button onClick={() => { const i = yearsAvail.indexOf(yearCur); if (i > 0) setYearSel(yearsAvail[i - 1]); }} className="bx-ghost" aria-label="Año siguiente">›</button>
            </div>

            {row && (
              <div className="mt-4 grid grid-cols-2 lg:grid-cols-4 gap-3">
                <Stat label={`Total ${yearCur}`} value={fmtP(row.tot.pips)} sub={unitL} tone={row.tot.pips > 0 ? "pos" : row.tot.pips < 0 ? "neg" : undefined} />
                <Stat label="Operaciones" value={row.tot.shown} sub="Cerradas y descartadas" />
                <Stat label="Win Rate anual" value={row.tot.wr === null ? "—" : `${row.tot.wr}%`} sub="BE no cuenta" tone={row.tot.wr !== null && row.tot.wr >= 50 ? "pos" : row.tot.wr !== null ? "neg" : undefined} />
                <Stat label="Meses en verde" value={`${posM} / ${actM}`} sub="Meses con operaciones" />
              </div>
            )}

            <div className="mt-4 overflow-x-auto">
              <table className="w-full text-center text-sm" style={{ minWidth: 980, borderCollapse: "separate", borderSpacing: 4 }}>
                <thead>
                  <tr className="text-[11px] uppercase tracking-wider bx-muted">
                    <th className="text-left px-2">Año</th>
                    {MONTHS_ES.map((mn) => <th key={mn} className="font-bold">{mn.slice(0, 3)}</th>)}
                    <th className="font-bold bx-accent">Total</th>
                  </tr>
                </thead>
                <tbody>
                  {yearTable.map((rw) => (
                    <tr key={rw.yy}>
                      <td className="text-left px-2 font-black" style={{ color: rw.yy === yearCur ? ACCENT : undefined }}>{rw.yy}</td>
                      {rw.monthsRow.map((c, i) => {
                        const has = c.st.shown > 0;
                        const bg = !has ? "rgba(var(--fg),.03)" : c.st.pips > 0 ? "rgba(16,185,129,.13)" : c.st.pips < 0 ? "rgba(244,63,94,.13)" : "#1B1B1B";
                        const bd = !has ? "var(--cardline)" : c.st.pips > 0 ? "rgba(16,185,129,.6)" : c.st.pips < 0 ? "rgba(244,63,94,.6)" : "var(--line2)";
                        return (
                          <td key={i} className="p-0">
                            <button
                              onClick={() => { setYm(c.key); setSelDay(null); setMode("month"); }}
                              aria-label={`${MONTHS_ES[i]} ${rw.yy}`}
                              className="w-full rounded-xl px-1 py-2 flex flex-col items-center"
                              style={{ background: bg, border: `1px solid ${bd}`, minHeight: 58 }}
                            >
                              {has ? (
                                <>
                                  <span className={`font-extrabold ${pnlColor(c.st.pips)}`}>{fmtP(c.st.pips)}</span>
                                  <span className="text-[10px] bx-muted leading-tight">{c.st.shown} {c.st.shown === 1 ? "trade" : "trades"}{c.st.wr !== null ? ` | ${c.st.wr}%` : ""}</span>
                                </>
                              ) : <span className="bx-muted text-xs">—</span>}
                            </button>
                          </td>
                        );
                      })}
                      <td className="p-0">
                        <div className="rounded-xl px-1 py-2 flex flex-col items-center" style={{ background: "rgba(var(--fg),.03)", border: `1px solid ${ACCENT}`, minHeight: 58 }}>
                          <span className={`font-black ${pnlColor(rw.tot.pips)}`}>{fmtP(rw.tot.pips)}</span>
                          <span className="text-[10px] bx-muted leading-tight">{rw.tot.shown} {rw.tot.shown === 1 ? "trade" : "trades"}{rw.tot.wr !== null ? ` | ${rw.tot.wr}%` : ""}</span>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p className="mt-3 text-[11px] bx-muted text-center">Toca un mes para ver su calendario diario y su curva de {unitL} acumulados.</p>
          </div>
        );
      })()}

      {mode === "month" && (<>
      {/* ---------- CALENDARIO ---------- */}
      <div className="bx-card p-3 md:p-4">
        <div className="flex items-center justify-center gap-3">
          <button onClick={() => go(-1)} className="bx-ghost" aria-label="Mes anterior" title="Mes anterior">‹</button>
          <div className="text-center" style={{ minWidth: 200 }}>
            <div className="text-lg md:text-xl font-black">{monthLabel(cur)}</div>
            <div className="text-[11px] bx-muted tracking-widest uppercase">Resultados en {unit}</div>
          </div>
          <button onClick={() => go(1)} className="bx-ghost" aria-label="Mes siguiente" title="Mes siguiente">›</button>
        </div>
        <div className="mt-3 flex flex-wrap items-center justify-center gap-2">
          <select className="bx-input" style={{ width: "auto", minWidth: 170 }} value={cur} onChange={(e) => { setYm(e.target.value); setSelDay(keepMonthSel()); }} aria-label="Elegir mes">
            {monthOptions.map((k) => <option key={k} value={k}>{monthLabel(k)}</option>)}
          </select>
          <button onClick={() => setSelDay(isMonthSel ? null : "__month__")} className={`bx-pill ${isMonthSel ? "on" : ""}`} data-testid="month-summary-btn">📊 Resumen del mes completo</button>
        </div>

        <div className="mt-2">
          <div>
            <div className="bx-calgrid gap-1 text-center text-[10px] sm:text-[11px] uppercase tracking-wider bx-muted mb-1" style={cols}>
              {WEEKDAYS.map((d) => <div key={d}>{d}</div>)}
              <div className="hidden sm:block">Semana</div>
            </div>

            {weeks.map((wk, wi) => (
              <div key={wi} className="bx-calgrid gap-1 mb-1" style={cols}>
                {wk.days.map((c, di) => {
                  if (!c) return <div key={di} />;
                  const { st } = c;
                  const has = st.shown > 0;
                  const border = !has ? "rgba(var(--fg),.09)" : st.pips > 0 ? "rgba(16,185,129,.55)" : st.pips < 0 ? "rgba(244,63,94,.55)" : "rgba(148,163,184,.4)";
                  const bg = !has ? "rgba(var(--fg),.02)" : st.pips > 0 ? "rgba(16,185,129,.12)" : st.pips < 0 ? "rgba(244,63,94,.12)" : "rgba(var(--fg),.06)";
                  const sel = selDay === c.key;
                  return (
                    <button
                      key={di}
                      onClick={() => setSelDay(sel ? null : c.key)}
                      aria-label={`Día ${c.d}`}
                      className="bx-day px-1 py-0.5 sm:p-1.5 flex flex-col text-left min-w-0"
                      style={{ height: "clamp(40px, 11vw, 58px)", background: bg, border: `1px solid ${border}`, boxShadow: has ? `0 0 12px ${st.pips > 0 ? "rgba(16,185,129,.18)" : st.pips < 0 ? "rgba(244,63,94,.18)" : "rgba(148,163,184,.12)"}` : undefined, outline: sel ? `2px solid ${ACCENT}` : "none", outlineOffset: 1 }}
                    >
                      <span className="text-[10px] sm:text-[11px] font-bold leading-none" style={{ color: c.key === today ? ACCENT : GREY }}>{c.d}</span>
                      {has && (
                        <span className={`text-[10px] sm:text-xs font-extrabold text-center my-auto leading-none whitespace-nowrap ${pnlColor(st.pips)}`}>{fmtDayPips(st.pips, "")}<span className="hidden sm:inline font-bold opacity-80">{unitL && !unitL.includes("/") ? ` ${unitL}` : ""}</span></span>
                      )}
                      {isAdmin && st.open > 0 && (
                        <span className="text-[9px] text-center" style={{ color: "var(--sky)" }}>⏳ {st.open}</span>
                      )}
                      {isAdmin && st.pending > 0 && (
                        <span className="text-[9px] text-center" style={{ color: "var(--amb)" }}>🕓 {st.pending}</span>
                      )}
                    </button>
                  );
                })}
                <div className="bx-day p-1 hidden sm:flex flex-col justify-center text-center" style={{ height: 58 }}>
                  <div className="text-[9px] uppercase tracking-wider bx-muted">Sem. {wi + 1}</div>
                  <div className={`text-xs font-extrabold ${pnlColor(wk.pips)}`}>{fmtP(wk.pips)}</div>
                  <div className="text-[9px] bx-muted">{wk.traded} {wk.traded === 1 ? "día" : "días"}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ---------- OPERACIONES DEL DÍA ---------- */}
      {selDay && (
        <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/70 p-3" onClick={() => setSelDay(null)} data-testid="day-modal">
        <div className="bx-card w-full max-w-xl flex flex-col p-3" style={{ maxHeight: "82vh" }} role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}>
          <div className="flex items-center justify-between gap-2 pb-2 shrink-0">
            <h3 className="font-extrabold text-sm md:text-base">{isMonthSel ? `Resumen consolidado de ${monthLabel(cur)}` : `${isAdmin ? "Operaciones del" : "Resumen del"} ${fmtDate(selDay)}`}</h3>
            <button onClick={() => setSelDay(null)} className="bx-ghost" style={{ padding: ".25rem .6rem" }} aria-label="Cerrar">✕</button>
          </div>
          {dayList.length === 0 ? (
            <div className="py-3 text-sm bx-muted">{isMonthSel ? "Sin operaciones este mes." : "Sin operaciones este día."}</div>
          ) : (
            <div className="overflow-y-auto min-h-0 pr-1" data-testid="day-scroll">
              {(() => {
                const ds = dayStats(dayList);
                return (
                  <div className="grid grid-cols-3 gap-2 text-center">
                    <div className="rounded-xl px-2 py-1.5" style={{ background: "rgba(var(--fg),.03)", border: "1px solid rgba(var(--fg),.09)" }}><div className="text-[11px] uppercase tracking-widest bx-muted">Resultado</div><div className={`text-xl font-black ${pnlColor(ds.pips)}`}>{fmtP(ds.pips)}</div><div className="text-xs bx-muted">{unitL}</div></div>
                    <div className="rounded-xl px-2 py-1.5" style={{ background: "rgba(var(--fg),.03)", border: "1px solid rgba(var(--fg),.09)" }}><div className="text-[11px] uppercase tracking-widest bx-muted">Trades</div><div className="text-xl font-black">{ds.shown}</div></div>
                    <div className="rounded-xl px-2 py-1.5" style={{ background: "rgba(var(--fg),.03)", border: "1px solid rgba(var(--fg),.09)" }}><div className="text-[11px] uppercase tracking-widest bx-muted">Win Rate</div><div className="text-xl font-black">{ds.wr === null ? "—" : `${ds.wr}%`}</div></div>
                  </div>
                );
              })()}
              <div className="mt-3 text-[11px] uppercase tracking-[0.18em] bx-muted">Detalle de operaciones · {dayList.length}</div>
              <div className="mt-2 space-y-2" data-testid="day-trades">
                {dayList.map((t, i) => (
                  <React.Fragment key={t.id}>
                    {isMonthSel && (i === 0 || dayList[i - 1].date !== t.date) && (
                      <div className="pt-2 text-[11px] uppercase tracking-[0.18em] bx-accent font-bold">{dayName(t.date)} {fmtDate(t.date)}</div>
                    )}
                    <DayTradeCard t={t} onOpen={isAdmin ? onOpen : null} onSignal={setSigTrade} />
                  </React.Fragment>
                ))}
              </div>
            </div>
          )}
        </div>
        </div>
      )}

      {sigTrade && <SignalModal t={sigTrade} onClose={() => setSigTrade(null)} />}

      {/* ---------- DASHBOARD DEL MES ---------- */}
      <div>
        <div className="text-center mb-3">
          <div className="text-[11px] tracking-[0.3em] font-bold bx-accent">MÉTRICAS DEL MES</div>
          <h2 className="mt-1 text-xl md:text-2xl font-black" style={{ color: "var(--ink)" }}>Resumen de {monthLabel(cur)}</h2>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <Stat label="Win Rate" value={`${m.winRate.toFixed(0)}%`} sub={`${m.wins} Wins / ${m.executed} Trades · BE no cuenta`} tone={m.winRate >= 50 && dec ? "pos" : dec ? "neg" : undefined} />
          <Stat label="R:R promedio" value={`${m.avgR >= 0 ? "+" : ""}${m.avgR.toFixed(2)}R`} sub={`Acumulado: ${m.totalR >= 0 ? "+" : ""}${m.totalR.toFixed(2)}R`} tone={m.avgR > 0 ? "pos" : m.avgR < 0 ? "neg" : undefined} />
          <Stat label="Total trades" value={m.total} sub={isAdmin ? `${m.executed} cerrados · ${m.open} activos · ${m.discarded} descartados` : "Cerradas y descartadas del mes"} />
        </div>

        <div className="bx-card p-3 md:p-4 mt-4" data-testid="month-curve">
          <div className="text-xs uppercase tracking-[0.18em] bx-muted mb-3">Curva de {unit} acumulados · {monthLabel(cur)}</div>
          {curve.length === 0 || !monthTrades.some(isPublic) && !isAdmin ? (
            <div className="text-sm bx-muted text-center py-8">Sin operaciones para dibujar la curva de este mes.</div>
          ) : (
            <div style={{ width: "100%", height: 260 }}>
              <ResponsiveContainer>
                <AreaChart data={curve} margin={{ top: 5, right: 10, left: 0, bottom: 0 }}>
                  <defs>
                    <linearGradient id="calFill" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor={ACCENT_HEX} stopOpacity={0.5} />
                      <stop offset="100%" stopColor={ACCENT_HEX} stopOpacity={0.02} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid stroke="rgba(128,134,150,.22)" vertical={false} />
                  <XAxis dataKey="d" tick={{ fill: GREY, fontSize: 10 }} tickLine={false} axisLine={false} interval="preserveStartEnd" />
                  <YAxis tick={{ fill: GREY, fontSize: 11 }} tickLine={false} axisLine={false} width={60} />
                  <Tooltip content={<ChartTooltip unit={unitL} />} />
                  <ReferenceLine y={0} stroke="var(--line2)" strokeDasharray="4 4" />
                  <Area type="monotone" dataKey="equity" name="Acumulado" stroke={ACCENT_HEX} strokeWidth={2.5} fill="url(#calFill)" />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          )}
          <div className="mt-1 text-[11px] bx-muted text-center">Eje horizontal: día del mes · acumulado progresivo de {unitL}</div>
        </div>

        <div className="grid lg:grid-cols-2 gap-4 mt-4">
          <div className="bx-card p-3 md:p-4">
            <div className="text-xs uppercase tracking-[0.18em] bx-muted mb-3">Desglose de operaciones</div>
            <div className="h-3 rounded-full overflow-hidden flex" style={{ background: "var(--cardline)" }} role="img" aria-label={`${m.wins} ganadoras, ${m.losses} perdedoras`}>
              {dec > 0 && (
                <>
                  <div data-testid="bar-wins" style={{ width: `${(m.wins / dec) * 100}%`, background: GREEN }} />
                  <div data-testid="bar-losses" style={{ width: `${(m.losses / dec) * 100}%`, background: RED }} />
                </>
              )}
            </div>
            <div className="mt-1 flex justify-between text-xs">
              <span className="text-emerald-400 font-bold">{m.wins} Wins</span>
              <span className="text-rose-400 font-bold">{m.losses} Losses</span>
            </div>
            <div className="mt-4 space-y-2 text-sm">
              {[
                ["TP · Ganadoras", m.wins, `${pct(m.wins)}%`, "text-emerald-400"],
                ["SL · Perdedoras", m.losses, `${pct(m.losses)}%`, "text-rose-400"],
                ["Break Even (BE)", m.be, `${pct(m.be)}%`, "text-white"],
              ].map(([label, n, p, cls]) => (
                <div key={label} className="flex items-center justify-between rounded-lg px-3 py-2" style={{ background: "rgba(var(--fg),.03)", border: "1px solid rgba(var(--fg),.09)" }}>
                  <span className="bx-muted">{label}</span>
                  <span className={`font-extrabold ${cls}`}>{n} <span className="bx-muted font-normal text-xs">({p})</span></span>
                </div>
              ))}
              {isAdmin && (
                <>
                  <div className="flex items-center justify-between rounded-lg px-3 py-2" style={{ background: "rgba(var(--fg),.03)", border: "1px solid rgba(var(--fg),.09)" }}>
                    <span className="bx-muted">Descartadas / Canceladas</span>
                    <span className="font-extrabold">{m.discarded}</span>
                  </div>
                  <div className="flex items-center justify-between rounded-lg px-3 py-2" style={{ background: "rgba(var(--fg),.03)", border: "1px solid rgba(var(--fg),.09)" }}>
                    <span className="bx-muted">Activas</span>
                    <span className="font-extrabold">{m.open}</span>
                  </div>
                  <div className="flex items-center justify-between rounded-lg px-3 py-2" style={{ background: "rgba(var(--fg),.03)", border: "1px solid rgba(var(--fg),.09)" }}>
                    <span className="bx-muted">Órdenes pendientes</span>
                    <span className="font-extrabold">{m.pending}</span>
                  </div>
                </>
              )}
            </div>
          </div>

          <div className="bx-card p-3 md:p-4">
            <div className="text-xs uppercase tracking-[0.18em] bx-muted mb-3">{unit} totales y extremos</div>
            <div className="text-center rounded-xl py-4" style={{ background: "rgba(var(--fg),.03)", border: "1px solid rgba(var(--fg),.09)" }}>
              <div className="text-[11px] uppercase tracking-widest bx-muted">Neto del mes</div>
              <div className={`text-4xl font-black ${pnlColor(m.totalPips)}`}>{fmtP(m.totalPips)}</div>
              <div className="text-xs bx-muted">{unitL}</div>
            </div>
            <div className="mt-3 grid grid-cols-2 gap-3">
              {[
                ["Mejor trade", best && best.pips > 0 ? best : null, "text-emerald-400"],
                ["Peor trade", worst && worst.pips < 0 ? worst : null, "text-rose-400"],
              ].map(([label, t, cls]) => (
                <button
                  key={label}
                  disabled={!t}
                  onClick={() => t && isAdmin && onOpen(t.id)}
                  className="rounded-xl p-3 text-center"
                  style={{ background: "rgba(var(--fg),.03)", border: "1px solid rgba(var(--fg),.09)", cursor: t && isAdmin ? "pointer" : "default" }}
                >
                  <div className="text-[11px] uppercase tracking-widest bx-muted">{label}</div>
                  {t ? (
                    <>
                      <div className={`mt-1 text-xl font-black ${cls}`}>{fmtP(t.pips)}</div>
                      <div className="text-xs bx-muted">{isAdmin ? `${t.asset} · ${t.direction} · ` : ""}{fmtDate(t.date)}</div>
                    </>
                  ) : (
                    <div className="mt-2 text-sm bx-muted">{label === "Peor trade" && closedTrades.length ? "Sin pérdidas" : "—"}</div>
                  )}
                </button>
              ))}
            </div>
          </div>
        </div>
        {monthTrades.length === 0 && <p className="mt-3 text-xs bx-ink2 text-center">No hay operaciones registradas en este mes.</p>}
      </div>
      </>)}
    </section>
  );
}

